(30560, 'frFR', '[DNT] Tools of Divination TRACKER', '', '', '', '', '', '', '', '', 19865),
(30561, 'frFR', '[DNT] Fun for the Little Ones TRACKER', '', '', '', '', '', '', '', '', 19865),
