(35627, 'frFR', 'Trésor : Corbeille de marchandises arakkoa', '', '', '', '', '', '', '', '', 19865),
(35628, 'frFR', 'La rangari Chel', '', '', '', '', '', '', '', '', 19865),
(35629, 'frFR', 'La redresseuse de torts Onaala', '', '', '', '', '', '', '', '', 19865),
