(37190, 'frFR', 'Iron Horde Invasion', '', '', '', '', '', '', '', '', 19865),
(37191, 'frFR', 'Sanketsu, la lame ardente', 'Apportez Sanketsu, la lame ardente, au Lieutenant Épine à votre fief.', 'La lame est brûlante au toucher. La gemme incrustée dans sa garde vous fixe comme pour vous mettre au défi de saisir l''épée.$b$bPeut-être qu’’elle intéressera quelqu’’un de votre fief.', '', '', '', '', '', '', 19865),
(37192, 'frFR', 'Sanketsu, la lame ardente', 'Apportez Sanketsu, la lame ardente au Maître de guerre Zog, à votre fief.', 'La lame est brûlante au toucher. La gemme incrustée dans sa garde vous fixe comme pour vous mettre au défi de saisir l''épée.$b$bPeut-être qu’’elle intéressera quelqu’’un de votre fief.', '', '', '', '', '', '', 19865),
(37193, 'frFR', 'The King''s Command', '', '', '', '', '', '', '', '', 19865),
(37194, 'frFR', 'A Flash of Bronze...', '', '', '', '', '', '', '', '', 19865),
(37195, 'frFR', 'The Dark Portal', '', '', '', '', '', '', '', '', 19865),
(37196, 'frFR', 'Iron Horde Invasion', '', '', '', '', '', '', '', '', 19865),
